            a *= 1 - 0.38 * sd * (1 - m)                                                                                                         # 影
            sh = np.clip(1.12 - 0.5 * dd + 0.28 * np.exp(-(((u - cx + rx * 0.35) / (rx * 0.5)) ** 2 + ((w - cy + ry * 0.4) / (ry * 0.5)) ** 2)), 0.3, 1.5)
            sh *= 1 - 0.16 * (np.sin((u - cx) / rx * 11 + (w - cy) / ry * 5) > 0.93)                                                             # 切れ目
            c = np.array(col, np.float32) * sh[..., None]
