    g = random.Random(1504); out = []
    for i in range(60):
        a = {'rank': str(i + 1), 'isin': f'XX{g.randrange(10**9, 10**10)}', 'name': f'銘柄{chr(0x30A2 + (i * 2) % 80)}{chr(0x30A2 + (i * 5 + 3) % 80)}・ホールディングス' if i % 4 else f'国債 第{300 + i}回', 'country': ['US', 'JP', 'GB', 'DE', 'FR', 'CH', 'TW', 'IN'][i % 8], 'assetClass': 'BOND' if i % 4 == 0 else 'EQUITY', 'sector': ['IT', 'HC', 'FN', 'EN', 'CD', 'CS', 'ID', 'TC'][(i * 3) % 8], 'quantity': str(g.randrange(10, 900) * 100),
             'bookValue': str(g.randrange(2 * 10**8, 9 * 10**8)), 'marketValue': str(g.randrange(2 * 10**8, 9 * 10**8)), 'weight': f'{3.2 - i * 0.045:.2f}', 'currency': ['USD', 'JPY', 'GBP', 'EUR', 'EUR', 'CHF', 'TWD', 'INR'][i % 8]}
        keys = list(a)
        if v and i in (4, 13, 27, 38, 52): keys = ['rank', 'isin', 'name', 'assetClass', 'country', 'sector', 'marketValue', 'bookValue', 'quantity', 'weight', 'currency']
        if v and i in (1, 9, 20, 33, 45, 58): a['marketValue'] = str(int(a['marketValue']) + (i + 3) * 1_370_000); a['weight'] = f'{float(a["weight"]) + (0.04 if i % 2 else -0.03):.2f}'
        if v and i == 20: a['quantity'] = str(int(a['quantity']) + 1200)
        out.append('<fd:Holding ' + ' '.join(f'{k}="{a[k]}"' for k in keys) + '/>')
    return out
